	var allHooks []PolicyHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Policy]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.WriteHooks[Policy]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Policy]{}, err
	}
