// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes PolicyChanges) Audit(policy PolicyAuditPolicy) (record.Model[Policy, foundryvalue.JSON[PolicyKey]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, err
	}
	var captured record.Field[Policy]
	captured, err = record.CaptureField[Policy]("id", codec.JSON[PolicyKey](), changes.fields.ID, policy.ID)
	if err != nil {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, err
	}
	captured, err = record.CaptureField[Policy]("name", codec.String[string](), changes.fields.Name, policy.Name)
	if err != nil {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Policy, foundryvalue.JSON[PolicyKey]]{}, err
	}
	return builder.Build()
}

