// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func PolicyAuditing(policy PolicyAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Policy]()
		if err != nil {
			return err
		}
		return RegisterPolicyObserver(registrar, pool, NewPolicyObserver(name), func(resolver foundation.Resolver) (func() PolicyHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() PolicyHooks {
				write := func(ctx context.Context, tx *database.Tx, changes PolicyChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return PolicyHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
